def move_items_to_general(apps, schema_editor):
    """Items now always have a sub-type. Any item filed under a bare main type moves to "<main> › General"."""
    Category = apps.get_model("resell", "Category")
    Link = apps.get_model("resell", "Item").categories.through
    for main in Category.objects.filter(parent__isnull=True):
        links = Link.objects.filter(category=main)
        if not links.exists():
            continue
        general = (Category.objects.filter(parent=main, name__iexact="General").first()
                   or Category.objects.create(name="General", parent=main))
        for link in links:
            Link.objects.get_or_create(item_id=link.item_id, category=general)
        links.delete()


